[CmdletBinding()]
param([string]$OutputDirectory = '_site')
$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$out=Join-Path $root $OutputDirectory;foreach($file in @('index.html','styles.css','site.js','search-index.json','.nojekyll')){if(-not(Test-Path (Join-Path $out $file) -PathType Leaf)){throw "Missing generated $file"}};$manifest=Get-Content (Join-Path $root 'docs-manifest.json') -Raw|ConvertFrom-Json;foreach($document in @($manifest.documents)){$relative=([IO.Path]::ChangeExtension($document,'.html')).Replace('/','\').ToLowerInvariant();if(-not(Test-Path (Join-Path $out $relative) -PathType Leaf)){throw "Missing generated page for $document"}};$index=Get-Content (Join-Path $out 'index.html') -Raw;if($index-notmatch'<title>Home · web-ccoedemo Node\.js</title>'){throw'Unexpected generated index title'};Write-Host "web-ccoedemo Node.js documentation validation passed for $($manifest.documents.Count) documents."
